// newTestRoutingEngine returns a baseline Inputs with two harnesses and a
// trivial catalog resolver. Mirrors the DDx newTestRunnerForRouting helper.
func newTestRoutingEngine() Inputs {
	return Inputs{
		Harnesses: []HarnessEntry{
			{
				Name:                "fiz",
				Surface:             "embedded-openai",
				CostClass:           "local",
				IsLocal:             true,
				AutoRoutingEligible: true,
				ExactPinSupport:     true,
				Available:           true,
				QuotaOK:             true,
				SubscriptionOK:      true,
				SupportedReasoning:  []string{"low", "medium", "high"},
				SupportedPerms:      []string{"safe", "supervised", "unrestricted"},
				SupportsTools:       true,
				Providers: []ProviderEntry{
					{
						Name:          "vidar-omlx",
						BaseURL:       "http://vidar:11434",
						DiscoveredIDs: []string{"Qwen3.6-35B-A3B-4bit", "MiniMax-M2.5-MLX-4bit"},
						SupportsTools: true,
						ContextWindows: map[string]int{
							"Qwen3.6-35B-A3B-4bit": 256000,
						},
					},
					{
						Name:          "openrouter",
						BaseURL:       "https://openrouter.ai/api/v1",
						DiscoveredIDs: []string{"qwen/qwen3.6", "anthropic/claude-sonnet-4-6"},
						SupportsTools: true,
					},
				},
			},
			{
				Name:                "codex",
				Surface:             "codex",
				CostClass:           "medium",
				IsSubscription:      true,
				AutoRoutingEligible: true,
				ExactPinSupport:     true,
				Available:           true,
				QuotaOK:             true,
				SubscriptionOK:      true,
				SupportedReasoning:  []string{"low", "medium", "high"},
				SupportedPerms:      []string{"safe", "supervised", "unrestricted"},
				SupportsTools:       true,
				DefaultModel:        "gpt-5.4",
			},
			{
				Name:                "claude",
				Surface:             "claude",
				CostClass:           "medium",
				IsSubscription:      true,
				AutoRoutingEligible: true,
				ExactPinSupport:     true,
				Available:           true,
				QuotaOK:             true,
				SubscriptionOK:      true,
				SupportedReasoning:  []string{"low", "medium", "high"},
				SupportedPerms:      []string{"safe", "supervised", "unrestricted"},
				SupportsTools:       true,
				DefaultModel:        "claude-sonnet-4-6",
			},
		},
		CatalogResolver: func(ref, surface string) (string, bool) {
			// Trivial test catalog.
			switch ref {
			case "cheap":
				if surface == "embedded-openai" {
					return "qwen/qwen3.6", true
				}
				if surface == "codex" {
					return "gpt-5.4-mini", true
				}
				if surface == "claude" {
					return "claude-haiku-4-6", true
				}
			case "smart":
				if surface == "claude" {
					return "claude-opus-4-7", true
				}
				if surface == "codex" {
					return "gpt-5.4", true
				}
			case "qwen/qwen3.6":
				if surface == "embedded-openai" {
					return "qwen/qwen3.6", true
				}
			}
			return "", false
		},
		Now: time.Date(2026, 4, 18, 0, 0, 0, 0, time.UTC),
	}
}

// === Smell 1: ddx-8610020e — Provider field present from day one ===
//
// RouteRequest carries Provider as a hard pin; the engine must never select
// a different provider when Provider is set.
func TestSmellProviderFieldDayOne(t *testing.T) {
	in := newTestRoutingEngine()

	// Provider pin: req.Provider constrains routing.
	req := Request{Profile: "cheap", Provider: "vidar-omlx"}
	dec, err := Resolve(req, in)
	if err != nil {
		t.Fatalf("Resolve: %v", err)
	}
	if dec.Provider != "vidar-omlx" {
		t.Errorf("provider=vidar-omlx soft pref: got %q, want vidar-omlx", dec.Provider)
	}

	// Hard pin: Harness=fiz + Provider=openrouter constrains routing.
	hardReq := Request{Harness: "fiz", Provider: "openrouter", Model: "qwen/qwen3.6"}
	dec2, err := Resolve(hardReq, in)
	if err != nil {
		t.Fatalf("hard pin Resolve: %v", err)
	}
	if dec2.Provider != "openrouter" {
		t.Errorf("hard pin: got provider=%q, want openrouter", dec2.Provider)
	}
}

func TestResolveServerInstanceIdentityFlowsThroughDecisionAndLoadResolver(t *testing.T) {
	var gotProvider, gotEndpoint, gotModel string
	in := Inputs{
		Harnesses: []HarnessEntry{
			{
				Name:                "fiz",
				Surface:             "embedded-openai",
				CostClass:           "local",
				IsLocal:             true,
				AutoRoutingEligible: true,
				ExactPinSupport:     true,
				Available:           true,
				QuotaOK:             true,
				SubscriptionOK:      true,
				SupportedReasoning:  []string{"low", "medium", "high"},
				SupportedPerms:      []string{"safe", "supervised", "unrestricted"},
				SupportsTools:       true,
				Providers: []ProviderEntry{
					{
						Name:           "local",
						BaseURL:        "http://grendel:8000/v1",
						ServerInstance: "shared-grendel",
						EndpointName:   "primary",
						DefaultModel:   "model-a",
						CostClass:      "local",
						SupportsTools:  true,
					},
				},
			},
		},
		ModelEligibility: func(model string) (ModelEligibility, bool) {
			if model != "model-a" {
				return ModelEligibility{}, false
			}
			return ModelEligibility{Power: 7, AutoRoutable: true}, true
		},
		EndpointLoadResolver: func(provider, endpoint, model string) (EndpointLoad, bool) {
			gotProvider, gotEndpoint, gotModel = provider, endpoint, model
			return EndpointLoad{NormalizedLoad: 0.25, UtilizationFresh: true}, true
		},
		Now: time.Date(2026, 4, 18, 0, 0, 0, 0, time.UTC),
	}

	dec, err := Resolve(Request{Harness: "fiz", Model: "model-a"}, in)
	if err != nil {
		t.Fatalf("Resolve: %v", err)
	}
	if dec == nil {
		t.Fatal("Resolve returned nil decision")
	}
	if dec.ServerInstance != "shared-grendel" {
		t.Fatalf("decision=%#v, want shared-grendel server instance", dec)
	}
	if len(dec.Candidates) != 1 {
		t.Fatalf("Candidates=%#v, want 1", dec.Candidates)
	}
	if dec.Candidates[0].ServerInstance != "shared-grendel" {
		t.Fatalf("candidate=%#v, want shared-grendel server instance", dec.Candidates[0])
	}
	if gotProvider != "local" || gotEndpoint != "shared-grendel" || gotModel != "model-a" {
		t.Fatalf("EndpointLoadResolver saw %q/%q/%q, want local/shared-grendel/model-a", gotProvider, gotEndpoint, gotModel)
	}
}

func TestExplicitProviderPinDoesNotSubstituteAvailableProvider(t *testing.T) {
	in := Inputs{
		Harnesses: []HarnessEntry{
			{
				Name:                "fiz",
				Surface:             "embedded-openai",
				CostClass:           "local",
				IsLocal:             true,
				AutoRoutingEligible: true,
				ExactPinSupport:     true,
				Available:           true,
				QuotaOK:             true,
				SubscriptionOK:      true,
				SupportsTools:       true,
				Providers: []ProviderEntry{
					{
						Name:               "lmstudio",
						DiscoveryAttempted: true,
						SupportsTools:      true,
					},
					{
						Name:          "openrouter",
						DiscoveredIDs: []string{"qwen/qwen3.6"},
						SupportsTools: true,
					},
				},
			},
		},
		Now: time.Date(2026, 4, 18, 0, 0, 0, 0, time.UTC),
	}

	dec, err := Resolve(Request{Provider: "lmstudio", Model: "qwen/qwen3.6"}, in)
	if err == nil {
		t.Fatalf("Resolve selected provider=%q model=%q, want no viable candidate", dec.Provider, dec.Model)
	}
	var noViable *NoViableCandidateError
	if !errors.As(err, &noViable) {
		t.Fatalf("error type=%T, want *NoViableCandidateError: %v", err, err)
	}
	if !strings.Contains(err.Error(), "provider=lmstudio") {
		t.Fatalf("error=%q, want provider pin detail", err.Error())
	}
	if dec == nil || dec.Harness != "" || dec.Provider != "" || dec.Model != "" {
		t.Fatalf("error decision selected a candidate: %#v", dec)
	}

	seenOpenRouter := false
	for _, c := range dec.Candidates {
		if c.Provider == "openrouter" {
			seenOpenRouter = true
			if c.Eligible {
				t.Fatalf("openrouter must not remain eligible under provider pin: %#v", c)
			}
			if c.FilterReason != FilterReasonPinMismatch {
				t.Fatalf("openrouter filter reason=%q, want %q", c.FilterReason, FilterReasonPinMismatch)
			}
			if !strings.Contains(c.Reason, "provider override requires lmstudio") {
				t.Fatalf("openrouter rejection reason=%q, want provider pin detail", c.Reason)
			}

package routing

import (
	"errors"
	"fmt"
	"strings"
	"testing"
	"time"
)

func TestRoutingPolicyInvariants(t *testing.T) {
	cases := []struct {
		policyStatement string
		req             Request
		inputs          Inputs
		wantHarness     string
		wantProvider    string
		wantEndpoint    string
		wantModel       string
		wantOnlyHarness string
		wantErrContains string
		wantRejected    map[string]FilterReason
	}{
		{
			policyStatement: "config only sets up provider sources; routing uses discovered inventory",
			req:             Request{Model: "configured-default"},
			inputs:          policyBaseInputs(),
			wantErrContains: "no live endpoint offers a match",
			wantRejected: map[string]FilterReason{
				"fiz/local": FilterReasonScoredBelowTop,
				"fiz/paid":  FilterReasonScoredBelowTop,
				"codex/":    FilterReasonScoredBelowTop,
			},
		},
		{
			policyStatement: "if no power provider is configured, use the best cheapest viable model",
			req:             Request{},
			inputs:          policyInputsWithoutPower(),
			wantHarness:     "fiz",
			wantProvider:    "local",
			wantModel:       "local-good",
		},
		{
			policyStatement: "if local LLMs are available and satisfy constraints, use them",
			req:             Request{MinPower: 7, MaxPower: 7},
			inputs:          policyInputsWithDiscoveredLocalDefault(),
			wantHarness:     "fiz",
			wantProvider:    "local",
			wantModel:       "local-good",
		},
		{
			policyStatement: "if local/free is unavailable, fall back to the best viable non-local candidate",
			req:             Request{MinPower: 7},
			inputs:          policyInputsWithLocalUnavailable(),
			wantHarness:     "codex",
			wantModel:       "cloud-frontier",
			wantRejected: map[string]FilterReason{
				"fiz/": FilterReasonUnhealthy,
			},
		},
		{
			policyStatement: "if local/free is below requested power, do not select it",
			req:             Request{MinPower: 8, MaxPower: 8},
			inputs:          policyInputsWithDiscoveredLocalDefault(),
			wantHarness:     "fiz",
			wantProvider:    "paid",
			wantModel:       "paid-strong",
			wantRejected: map[string]FilterReason{
				"fiz/local": FilterReasonBelowMinPower,
			},
		},
		{
			policyStatement: "an exact model pin overrides local preference",
			req:             Request{Model: "paid-strong"},
			inputs:          policyInputsWithDiscoveredLocalDefault(),
			wantHarness:     "fiz",
			wantProvider:    "paid",
			wantModel:       "paid-strong",
			wantRejected: map[string]FilterReason{
				"fiz/local": FilterReasonScoredBelowTop,
			},
		},
		{
			policyStatement: "a provider endpoint pin is exclusive",
			req:             Request{Provider: "paid@secondary", Model: "paid-strong"},
			inputs:          policyInputsWithProviderEndpoints(),
			wantHarness:     "fiz",
			wantProvider:    "paid@secondary",
			wantEndpoint:    "secondary",
			wantModel:       "paid-strong",
			wantRejected: map[string]FilterReason{
				"fiz/paid@primary": FilterReasonPinMismatch,
			},
		},
		{
			policyStatement: "a harness pin is exclusive",
			req:             Request{Harness: "codex", Model: "cloud-frontier"},
			inputs:          policyBaseInputs(),
			wantHarness:     "codex",
			wantModel:       "cloud-frontier",
			wantOnlyHarness: "codex",
		},
		{
			policyStatement: "unknown-power models remain routable when no power bound is requested",
			req:             Request{},
			inputs:          policyInputsWithUnknownPowerModel(),
			wantHarness:     "fiz",
			wantProvider:    "local",
			wantModel:       "local-good",
		},
		{
			policyStatement: "unknown-power exact pins are allowed",
			req:             Request{Model: "unknown-model"},
			inputs:          policyInputsWithUnknownPowerModel(),
			wantHarness:     "fiz",
			wantProvider:    "unknown",
			wantModel:       "unknown-model",
		},
		{
			policyStatement: "provider/deployment class keeps local community models below cloud frontier when benchmarks tie",
			req:             Request{},
			inputs:          policyInputsWithTiedBenchmarks(),
			wantHarness:     "codex",
			wantModel:       "cloud-frontier",
		},
	}

	for _, tc := range cases {
		t.Run(tc.policyStatement, func(t *testing.T) {
			dec, err := Resolve(tc.req, tc.inputs)
			if tc.wantErrContains != "" {
				if err == nil {
					t.Fatalf("policy_statement=%q: Resolve succeeded with decision=%#v, want error containing %q", tc.policyStatement, dec, tc.wantErrContains)
				}
				if !strings.Contains(err.Error(), tc.wantErrContains) {
					t.Fatalf("policy_statement=%q: error=%q, want contains %q", tc.policyStatement, err.Error(), tc.wantErrContains)
				}
			} else if err != nil {
				t.Fatalf("policy_statement=%q: Resolve error: %v", tc.policyStatement, err)
			}

			if tc.wantHarness != "" && dec.Harness != tc.wantHarness {
				t.Fatalf("policy_statement=%q: harness=%q, want %q; candidates=%s", tc.policyStatement, dec.Harness, tc.wantHarness, policyCandidateSummary(dec.Candidates))
			}
			if tc.wantProvider != "" && dec.Provider != tc.wantProvider {
				t.Fatalf("policy_statement=%q: provider=%q, want %q; candidates=%s", tc.policyStatement, dec.Provider, tc.wantProvider, policyCandidateSummary(dec.Candidates))
			}
			if tc.wantEndpoint != "" && dec.Endpoint != tc.wantEndpoint {
				t.Fatalf("policy_statement=%q: endpoint=%q, want %q; candidates=%s", tc.policyStatement, dec.Endpoint, tc.wantEndpoint, policyCandidateSummary(dec.Candidates))
			}
			if tc.wantModel != "" && dec.Model != tc.wantModel {
				t.Fatalf("policy_statement=%q: model=%q, want %q; candidates=%s", tc.policyStatement, dec.Model, tc.wantModel, policyCandidateSummary(dec.Candidates))
			}
			if tc.wantOnlyHarness != "" {
				for _, candidate := range dec.Candidates {
					if candidate.Harness != tc.wantOnlyHarness {
						t.Fatalf("policy_statement=%q: candidate harness=%q, want only %q; candidates=%s", tc.policyStatement, candidate.Harness, tc.wantOnlyHarness, policyCandidateSummary(dec.Candidates))
					}
				}
			}
			for key, want := range tc.wantRejected {
				candidate, ok := policyCandidateByKey(dec.Candidates, key)
				if !ok {
					t.Fatalf("policy_statement=%q: candidate %q not found in %s", tc.policyStatement, key, policyCandidateSummary(dec.Candidates))
				}
				if candidate.Eligible {
					t.Fatalf("policy_statement=%q: candidate %q remained eligible, want rejected with %q", tc.policyStatement, key, want)
				}
				if candidate.FilterReason != want {
					t.Fatalf("policy_statement=%q: candidate %q filter_reason=%q, want %q; reason=%q", tc.policyStatement, key, candidate.FilterReason, want, candidate.Reason)
				}
			}
		})
	}
}

func TestRoutingPolicyNoCandidateCarriesRejectedTrace(t *testing.T) {
	policyStatement := "no-candidate errors expose rejected candidate reasons for caller retry decisions"
	dec, err := Resolve(Request{MinPower: 9, MaxPower: 9}, policyBaseInputs())
	if err == nil {
		t.Fatalf("policy_statement=%q: Resolve succeeded with decision=%#v, want no viable candidate", policyStatement, dec)
	}
	var noViable *NoViableCandidateError
	if !errors.As(err, &noViable) {
		t.Fatalf("policy_statement=%q: error=%T %v, want NoViableCandidateError", policyStatement, err, err)
	}
	if noViable.MinPower != 9 || noViable.MaxPower != 9 {
		t.Fatalf("policy_statement=%q: bounds min=%d max=%d, want 9/9", policyStatement, noViable.MinPower, noViable.MaxPower)
	}
	if len(dec.Candidates) == 0 {
		t.Fatalf("policy_statement=%q: rejected trace is empty", policyStatement)
	}
	for _, c := range dec.Candidates {
		if c.Eligible || c.FilterReason == FilterReasonEligible {
			t.Fatalf("policy_statement=%q: candidate=%#v, want rejected candidate with typed reason", policyStatement, c)
		}
	}
}

