package serviceimpl

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"sort"
	"strings"
	"time"

	"github.com/DocumentDrivenDX/fizeau/internal/session"
)

// SessionLogEntry is an API-neutral projection of one service session log.
type SessionLogEntry struct {
	SessionID string
	ModTime   time.Time
	Size      int64
}

// UsageReport aggregates session usage from the service-owned log directory.
func UsageReport(ctx context.Context, logDir string, opts session.UsageOptions) (*session.UsageReport, error) {
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	return session.AggregateUsage(logDir, opts)
}

// ListSessionLogs returns JSONL session logs sorted by session ID.
func ListSessionLogs(ctx context.Context, logDir string) ([]SessionLogEntry, error) {
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	if logDir == "" {
		return nil, nil
	}
	entries, err := os.ReadDir(logDir)
	if err != nil {
		return nil, err
	}
	out := make([]SessionLogEntry, 0, len(entries))
	for _, e := range entries {
		if e.IsDir() || !strings.HasSuffix(e.Name(), ".jsonl") {
			continue
		}
		id := strings.TrimSuffix(e.Name(), ".jsonl")
		entry := SessionLogEntry{SessionID: id}
		if info, err := e.Info(); err == nil && info != nil {
			entry.ModTime = info.ModTime()
			entry.Size = info.Size()
		}
		out = append(out, entry)
	}
	sort.Slice(out, func(i, j int) bool { return out[i].SessionID < out[j].SessionID })
	return out, nil
}

// WriteSessionLog writes the raw session events as indented JSON objects.
func WriteSessionLog(ctx context.Context, path string, w io.Writer) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	events, err := session.ReadEvents(path)
	if err != nil {
		return err
	}
	for _, e := range events {
		data, err := json.MarshalIndent(e, "", "  ")
		if err != nil {
			return err
		}
		if _, err := fmt.Fprintln(w, string(data)); err != nil {
			return err
		}
	}
	return nil
}

// ReplaySession renders a human-readable transcript for one session log path.
func ReplaySession(ctx context.Context, path string, w io.Writer) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	return session.Replay(path, w)
}

package routing

import (
	"fmt"
	"strings"

	"github.com/DocumentDrivenDX/fizeau/internal/reasoning"
)

// Capabilities describes what a (harness, provider, model) tuple can do.
// Populated from harness config + catalog metadata + provider discovery.
type Capabilities struct {
	ContextWindow      int      // resolved tokens; 0 = unknown
	SupportsTools      bool     // supports tool/function calling
	SupportsStreaming  bool     // supports streaming responses
	SupportedReasoning []string // supported public reasoning values
	MaxReasoningTokens int      // 0 means numeric reasoning is unsupported/unknown
	SupportedPerms     []string // {"safe","supervised","unrestricted"} subset
	ExactPinSupport    bool     // accepts exact concrete model pins
	SupportedModels    []string // nil = no static allow-list
}

// HasReasoning returns true if the candidate supports the requested reasoning
// value. Empty, auto, off, and numeric 0 impose no requirement.
func (c Capabilities) HasReasoning(value string) bool {
	policy, err := reasoning.ParseString(value)
	if err != nil {
		return false
	}
	switch policy.Kind {
	case reasoning.KindUnset, reasoning.KindAuto, reasoning.KindOff:
		return true
	case reasoning.KindTokens:
		return c.MaxReasoningTokens > 0 && policy.Tokens <= c.MaxReasoningTokens
	case reasoning.KindNamed:
		for _, supported := range c.SupportedReasoning {
			normalized, err := reasoning.Normalize(supported)
			if err == nil && normalized == policy.Value {
				return true
			}
		}
		return false
	default:
		return false
	}
}

// HasPermissions returns true if the candidate supports the requested level.
// An empty permission level always returns true.
func (c Capabilities) HasPermissions(perm string) bool {
	if perm == "" {
		return true
	}
	for _, p := range c.SupportedPerms {
		if strings.EqualFold(p, perm) {
			return true
		}
	}
	return false
}

// HasModel returns true when the exact model pin is within the static
// harness allow-list. A nil allow-list means the harness delegates validation
// to provider-side model checks.
func (c Capabilities) HasModel(model string) bool {
	if c.SupportedModels == nil || model == "" {
		return true
	}
	for _, supported := range c.SupportedModels {
		if supported == model {
			return true
		}
	}
	return false
}

// CheckGating applies all capability gates against a request and returns
// the first failure reason (free-form string for diagnostics) plus the
// typed FilterReason category for the failure. Returns ("", FilterReasonEligible)
// when all gates pass.
//
// The typed return is the authoritative classification — callers must not
// re-classify by parsing the string. The string is for human-readable
// diagnostics only.
//
// Fixes ddx-4817edfd subtree: pre-dispatch capability check covering
// context window, tool support, effort, permissions.
func CheckGating(cap Capabilities, req Request) (string, FilterReason) {
	// Context window gating: if the request declares prompt size or an effort
	// that implies a minimum context, reject candidates that can't fit.
	minCtx := req.MinContextWindow()
	if minCtx > 0 && cap.ContextWindow > 0 && cap.ContextWindow < minCtx {
		return fmt.Sprintf("context window %d < required %d", cap.ContextWindow, minCtx), FilterReasonContextTooSmall
	}

	// Tool-calling support gating.
	if req.RequiresTools && !cap.SupportsTools {
		return "tool calling not supported", FilterReasonNoToolSupport
	}

	if !cap.HasReasoning(req.Reasoning) {
		return fmt.Sprintf("reasoning %q not supported", req.Reasoning), FilterReasonReasoningUnsupported
	}

	// Permissions support gating.
	if !cap.HasPermissions(req.Permissions) {
		return fmt.Sprintf("permissions %q not supported", req.Permissions), FilterReasonScoredBelowTop
	}

	if req.Model != "" && !cap.HasModel(req.Model) {
		return "model not in harness allow-list", FilterReasonScoredBelowTop
	}

	// Exact-pin gating: an explicit Model field requires ExactPinSupport.
	if req.Model != "" && req.ModelRef == "" && !cap.ExactPinSupport {
		return "exact model pin not supported", FilterReasonScoredBelowTop
	}

	return "", FilterReasonEligible
}

// CheckPowerEligibility applies catalog-power gates for unpinned automatic
// routing. Any explicit hard route pin (harness, provider, or model) bypasses
// this gate so caller-chosen routes are never broadened or overridden by
// power policy.
func CheckPowerEligibility(lookup func(string) (ModelEligibility, bool), model string, req Request) (string, FilterReason) {
	if req.Model != "" || req.Provider != "" || req.Harness != "" || lookup == nil {
		return "", FilterReasonEligible
	}
	if model == "" {
		return "model has no catalog power metadata", FilterReasonPowerMissing
	}
	eligibility, ok := lookup(model)
	if !ok {
		if req.MinPower > 0 || req.MaxPower > 0 {
			return fmt.Sprintf("model %q has no catalog power metadata", model), FilterReasonPowerMissing
		}
		return "", FilterReasonEligible
	}
	if eligibility.ExactPinOnly {
		return fmt.Sprintf("model %q is exact-pin-only", model), FilterReasonExactPinOnly
	}
	if !eligibility.AutoRoutable {
		if eligibility.Power <= 0 {
			return fmt.Sprintf("model %q has no catalog power metadata", model), FilterReasonPowerMissing
		}
		return fmt.Sprintf("model %q is not auto-routable", model), FilterReasonNotAutoRoutable
	}
	if req.MinPower > 0 && eligibility.Power < req.MinPower {
		return fmt.Sprintf("model %q power %d < min_power %d", model, eligibility.Power, req.MinPower), FilterReasonBelowMinPower
	}
	if req.MaxPower > 0 && eligibility.Power > req.MaxPower {
		return fmt.Sprintf("model %q power %d > max_power %d", model, eligibility.Power, req.MaxPower), FilterReasonAboveMaxPower
	}
	return "", FilterReasonEligible
}

// resolveRequestReasoning returns a copy of req with Reasoning resolved to the
// catalog's surface_policy reasoning_default for the request's profile/surface
// when the request asks for Reasoning=auto. This must run before CheckGating
// so candidates that only support a different reasoning level (e.g. an
// off-only variant under a profile whose surface default is "high") are
// correctly disqualified by the capability gate. Other Reasoning values
// (unset, off, named, numeric) are left untouched, preserving the existing
// behavior of those code paths.
func resolveRequestReasoning(req Request, surface string, resolver func(profile, surface string) (string, bool)) Request {
	if resolver == nil || req.Profile == "" {
		return req
	}
	policy, err := reasoning.ParseString(req.Reasoning)
	if err != nil || policy.Kind != reasoning.KindAuto {
		return req
	}
	resolved, ok := resolver(req.Profile, surface)
	if !ok || resolved == "" {
		return req
	}
	out := req
	out.Reasoning = resolved
	return out
}

	if harness == "local" {
		return "fiz"
	}
	return harness
}

func findHarness(harnesses []HarnessEntry, name string) (HarnessEntry, bool) {
	for _, h := range harnesses {
		if h.Name == name {
			return h, true
		}
	}
	return HarnessEntry{}, false
}

func harnessSupportsModel(supported []string, model string) bool {
	for _, candidate := range supported {
		if candidate == model {
			return true
		}
	}
	return false
}

func explicitProfileConstraint(profile, providerPreference string) (string, bool) {
	switch providerPreference {
	case ProviderPreferenceLocalOnly:
		return ProviderPreferenceLocalOnly, true
	case ProviderPreferenceSubscriptionOnly:
		return ProviderPreferenceSubscriptionOnly, true
	}
	switch profile {
	case "local", "offline", "air-gapped":
		return ProviderPreferenceLocalOnly, true
	case "smart", "code-smart":
		return ProviderPreferenceSubscriptionOnly, true
	default:
		return "", false
	}
}

func harnessViolatesProfileConstraint(h HarnessEntry, constraint string) bool {
	switch constraint {
	case ProviderPreferenceLocalOnly:
		return !h.IsLocal
	case ProviderPreferenceSubscriptionOnly:
		return !h.IsSubscription
	default:
		return false
	}
}

func modelPinViolatesProfileConstraint(model string, in Inputs, constraint string) bool {
	var constrainedCanServe bool
	var outsideCanServe bool
	for _, h := range in.Harnesses {
		if h.TestOnly || !h.AutoRoutingEligible {
			continue
		}
		if !harnessCanServeExactModel(h, model) {
			continue
		}
		if harnessViolatesProfileConstraint(h, constraint) {
			outsideCanServe = true
		} else {
			constrainedCanServe = true
		}
	}
	return !constrainedCanServe && outsideCanServe
}

func harnessCanServeExactModel(h HarnessEntry, model string) bool {
	if len(h.SupportedModels) > 0 && harnessSupportsModel(h.SupportedModels, model) {
		return true
	}
	if h.DefaultModel == model {
		return true
	}
	providers := h.Providers
	if len(providers) == 0 {
		providers = []ProviderEntry{{Name: ""}}
	}
	for _, p := range providers {
		if p.DefaultModel == model {
			return true
		}
		if len(p.DiscoveredIDs) > 0 && FuzzyMatch(model, p.DiscoveredIDs) != "" {
			return true
		}
	}
	return false
}

func missingProfileCapability(req Request) string {
	if req.Profile == "" {
		return ""
	}
	switch req.ProviderPreference {
	case ProviderPreferenceLocalOnly:
		return "local endpoint"
	case ProviderPreferenceSubscriptionOnly:
		return "subscription harness"
	default:
		return ""
	}
}

func requestedModelIntent(req Request) string {
	switch {
	case req.Model != "":
		return req.Model
	case req.ModelRef != "":
		return req.ModelRef
	default:
		return ""
	}
}

func hasLiveDiscoveryCandidates(candidates []rankedCandidate) bool {
	for _, c := range candidates {
		if c.out.Provider != "" && c.internal.Model == "" {
			return true
		}
		if c.out.Provider != "" && c.out.Reason != "" {
			return true
		}
	}
	return false
}

type rankedCandidate struct {
	out      Candidate
	internal candidateInternal
	// quotaExhaustedRetryAfter is non-zero when this candidate would have been
	// eligible save for its provider being in the quota_exhausted state.
	// Resolve uses this to detect the "all eligible providers quota-exhausted"
	// case and surface ErrAllProvidersQuotaExhausted.
	quotaExhaustedRetryAfter time.Time
}

// buildHarnessCandidates expands one HarnessEntry into 1..N candidates, one
// per (harness, provider, resolved-model) tuple.
func buildHarnessCandidates(h HarnessEntry, req Request, in Inputs) []rankedCandidate {
	caps := Capabilities{
		SupportsTools:      h.SupportsTools,
		SupportedReasoning: h.SupportedReasoning,
		MaxReasoningTokens: h.MaxReasoningTokens,
		SupportedPerms:     h.SupportedPerms,
		ExactPinSupport:    h.ExactPinSupport,
		SupportedModels:    h.SupportedModels,
	}

	if !h.Available {
		return []rankedCandidate{{
			out: Candidate{
				Harness:      h.Name,
				CostSource:   CostSourceUnknown,
				Reason:       "harness not available",
				FilterReason: FilterReasonUnhealthy,
			},
			internal: candidateInternal{Harness: h.Name, CostClass: h.CostClass, CostSource: CostSourceUnknown},
		}}
	}

	histRate, hasHist := in.HistoricalSuccess[h.Name]
	if !hasHist {
		histRate = -1
	}

	// Enumerate providers. For harnesses with no providers (subprocess harnesses
	// with vendor-managed billing), emit a single virtual provider entry.
	providers := h.Providers
	if len(providers) == 0 {
		providers = []ProviderEntry{{Name: ""}}
	}

	out := make([]rankedCandidate, 0, len(providers))
	minCtx := req.MinContextWindow()
	for _, p := range providers {
		model, reason := resolveModel(h, p, req, in)
		ctxWin := 0
		ctxSrc := ContextSourceUnknown
		if p.ContextWindows != nil {
			if v, ok := p.ContextWindows[model]; ok {
				ctxWin = v
			}
		}
		if ctxWin > 0 && p.ContextWindowSources != nil {
			if src, ok := p.ContextWindowSources[model]; ok && src != "" {
				ctxSrc = src
			}
		}
		if ctxWin == 0 && p.ContextWindow > 0 {
			ctxWin = p.ContextWindow
			if p.ContextWindowSource != "" {
				ctxSrc = p.ContextWindowSource
			}
		}
		if ctxWin == 0 && model != "" {
			ctxWin = 131072
			ctxSrc = ContextSourceDefault
		}
		if model == "" {
			ctxSrc = ContextSourceUnknown
		}
		entryCaps := caps
		entryCaps.ContextWindow = ctxWin
		entryCaps.SupportsTools = caps.SupportsTools || p.SupportsTools
		if len(p.DiscoveredIDs) > 0 {
			entryCaps.SupportedModels = nil
		}

		key := ProviderModelKey(p.Name, p.EndpointName, model)
		obs := in.ObservedSpeedTPS[key]
		if obs == 0 && p.EndpointName != "" {
			obs = in.ObservedSpeedTPS[ProviderModelKey(p.Name, "", model)]
		}
		providerSuccessRate := -1.0
		if rate, ok := in.ProviderSuccessRate[key]; ok {
			providerSuccessRate = rate
		} else if p.EndpointName != "" {
			if rate, ok := in.ProviderSuccessRate[ProviderModelKey(p.Name, "", model)]; ok {
				providerSuccessRate = rate
			}
		}
		latencyMS := in.ObservedLatencyMS[key]
		if latencyMS == 0 && p.EndpointName != "" {
			latencyMS = in.ObservedLatencyMS[ProviderModelKey(p.Name, "", model)]
		}
		power := candidatePower(in.ModelEligibility, model)
		endpointLoad := EndpointLoad{}
		if in.EndpointLoadResolver != nil {
			loadProvider, loadEndpoint := candidateLoadIdentity(h, p)
			if resolved, ok := in.EndpointLoadResolver(loadProvider, loadEndpoint, model); ok {
				endpointLoad = resolved
			}
		} else if load, ok := in.EndpointLoads[key]; ok {
			endpointLoad = load
		}

		gateReq := resolveRequestReasoning(req, h.Surface, in.ReasoningResolver)

		eligible := true
		var filterReason FilterReason
		if reason == "" {
			// Subscription quota is a hard availability gate and must be
			// reported before catalog metadata gates. An exhausted Claude/Codex/
			// Gemini account is never a viable candidate, regardless of whether
			// the resolved model has complete power metadata.
			if h.IsSubscription && !h.SubscriptionOK {
				eligible = false
				reason = h.QuotaReason
				if reason == "" {
					if h.QuotaStale {
						reason = "subscription quota unavailable"
					} else {
						reason = "subscription quota exhausted"
					}
				}
				filterReason = FilterReasonUnhealthy
			} else if g, fr := CheckPowerEligibility(in.ModelEligibility, model, gateReq); g != "" {
				eligible = false
				reason = g
				filterReason = fr
			} else if g, fr := CheckGating(entryCaps, gateReq); g != "" {
				eligible = false
				reason = g
				filterReason = fr
			}
		} else {
			eligible = false
			// resolveModel rejection — model resolution is a capability
			// mismatch with no specific public category, so fall through
			// to the catch-all.
			filterReason = FilterReasonScoredBelowTop
		}

		// Hard preference filtering.
		if eligible {
			switch req.ProviderPreference {
			case ProviderPreferenceLocalOnly:
				if !h.IsLocal {
					eligible = false
					reason = "preference is local-only"
					filterReason = FilterReasonUnhealthy
				}
			case ProviderPreferenceSubscriptionOnly:
				if !h.IsSubscription {
					eligible = false
					reason = "preference is subscription-only"
					filterReason = FilterReasonUnhealthy
				}
			}
		}

		if eligible && req.Provider != "" && req.Provider != candidateProviderIdentity(h, p) {
			// Hard provider pin: reject every other provider identity, even
			// when a non-pinned candidate would otherwise score higher.
			eligible = false
			reason = fmt.Sprintf("provider override requires %s", req.Provider)
			filterReason = FilterReasonPinMismatch
		}

		inCooldown := false
		if p.Name != "" && p.InCooldown {
			inCooldown = true
		} else if p.Name != "" && in.CooldownDuration > 0 {
			if failedAt, ok := in.ProviderCooldowns[p.Name]; ok {
				if in.Now.Sub(failedAt) < in.CooldownDuration {
					inCooldown = true
				}
			}
		}

		// Provider quota-exhausted gate. The state machine lives in the
		// service layer; the engine consumes the projected map of
		// provider-name → retry_after. Apply only when the candidate would
		// otherwise have been eligible — disqualifying an already-rejected
		// candidate with a different reason would lose the original signal.
		var quotaExhaustedRetryAfter time.Time
		if eligible {
			providerKey := candidateProviderIdentity(h, p)
			if providerKey != "" && len(in.ProviderQuotaExhaustedUntil) > 0 {
				if retryAfter, ok := in.ProviderQuotaExhaustedUntil[providerKey]; ok && retryAfter.After(in.Now) {
					eligible = false
					reason = fmt.Sprintf("provider %s quota exhausted until %s", providerKey, retryAfter.Format(time.RFC3339))
					filterReason = FilterReasonQuotaExhausted
					quotaExhaustedRetryAfter = retryAfter
				}
			}
		}

		ci := candidateInternal{
			Harness:               h.Name,
			Provider:              p.Name,
			EndpointName:          p.EndpointName,
			ServerInstance:        p.ServerInstance,
			Model:                 model,
			CostClass:             candidateCostClass(h, p),
			CostUSDPer1kTokens:    p.CostUSDPer1kTokens,
			CostSource:            normalizeCostSource(p.CostSource),
			Power:                 power,
			ContextLength:         ctxWin,
			ContextSource:         ctxSrc,
			IsSubscription:        h.IsSubscription,
			QuotaOK:               h.QuotaOK,
			QuotaPercentUsed:      h.QuotaPercentUsed,
			QuotaStale:            h.QuotaStale,
			QuotaTrend:            h.QuotaTrend,
			SubscriptionOK:        h.SubscriptionOK,
			HistoricalSuccessRate: histRate,
			ProviderSuccessRate:   providerSuccessRate,
			ObservedTokensPerSec:  obs,
			ObservedLatencyMS:     latencyMS,
			InCooldown:            inCooldown || h.InCooldown,
			ProviderAffinityMatch: req.Provider != "" && req.Provider == candidateProviderIdentity(h, p),
			ProviderPreference:    req.ProviderPreference,
			EndpointLoad:          endpointLoad.NormalizedLoad,
			EndpointLoadFresh:     endpointLoad.UtilizationFresh,
			EndpointSaturated:     endpointLoad.UtilizationSaturated,
		}

